/** Which Gospels each of Eusebius' ten tables lists (Letter to Carpianus). */
export const CANON_LABELS: Record<number, string> = {
  1: 'Matthew, Mark, Luke, John',
  2: 'Matthew, Mark, Luke',
  3: 'Matthew, Luke, John',
  4: 'Matthew, Mark, John',
  5: 'Matthew, Luke',
  6: 'Matthew, Mark',
  7: 'Matthew, John',
  8: 'Mark, Luke',
  9: 'Luke, John',
  10: 'Unique to one Gospel',
}

export const ROMAN = ['', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X']

export interface EusebianSection {
  gospel: Gospel
  section: number
  canons: number[]          // empty = outside Eusebius' tables (Mark's longer ending)
  startCh: number; startV: number; startPart: string
  endCh: number; endV: number; endPart: string
}

export interface VerseParallels extends EusebianSection {
  parallels: EusebianSection[]
}

export function isGospel(book: string): book is Gospel {
  return (GOSPELS as string[]).includes(book)
}

function toSection(gospel: Gospel, t: SectionTuple): EusebianSection {
  const [section, canons, startCh, startV, startPart, endCh, endV, endPart] = t
  return { gospel, section, canons, startCh, startV, startPart, endCh, endV, endPart }
}

/** Section by gospel index (1-4) * 1000 + number — the encoding used in SectionTuple parallels. */
function sectionById(id: number): EusebianSection {
  const gospel = GOSPELS[Math.floor(id / 1000) - 1]
  return toSection(gospel, SECTIONS[gospel][(id % 1000) - 1])
}

/**
 * Sections containing a verse, each with its Eusebian parallels. Usually one; two when
 * the verse is split between sections (Mark 1:7 → §3 "1:4-7a" and §4 "1:7b-8").
 * ponytail: linear scan of ≤355 tuples — trivially fast, no index needed.
 */
export function parallelsForVerse(book: string, chapter: number, verse: number): VerseParallels[] {
  if (!isGospel(book)) return []
  const at = chapter * 1000 + verse
  return SECTIONS[book]
    .filter(t => t[2] * 1000 + t[3] <= at && at <= t[5] * 1000 + t[6])
    .sort((a, b) => a[2] * 1000 + a[3] - (b[2] * 1000 + b[3]))
    .map(t => ({ ...toSection(book, t), parallels: t[8].map(sectionById) }))
}

/** "1:7b–8", "1:19–2:4", "3:16b–e" */
export function formatRange(s: EusebianSection): string {
  const start = `${s.startCh}:${s.startV}${s.startPart}`
  if (s.startCh === s.endCh && s.startV === s.endV) {
    return s.endPart && s.endPart !== s.startPart ? `${start}–${s.endPart}` : start
  }
  const end = s.startCh === s.endCh ? `${s.endV}${s.endPart}` : `${s.endCh}:${s.endV}${s.endPart}`
  return `${start}–${end}`
}
